const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{height:100%;color:var(--ink);font:13px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif;--big:24px}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x6\"]{--big:26px}\n.card[data-size=\"6x3\"]{--big:20px}\n.card[data-size=\"6x6\"]{--big:40px}\n.shell{width:100%;height:100%;display:flex;flex-direction:column;gap:6px;padding:10px;min-width:0;min-height:0;overflow:hidden}\n.card[data-size=\"3x3\"] .shell{padding:8px;gap:5px}\n.card[data-size=\"6x6\"] .shell{padding:14px;gap:10px}\n\n/* \u6309\u94ae\u4e0e\u8f93\u5165 */\n.btn{font:inherit;font-size:12px;min-height:28px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--panel-paper));color:var(--ink);cursor:pointer;white-space:nowrap;flex:none}\n.btn.icon{width:28px;padding:0;font-size:16px;line-height:1}\n.btn.pri{background:var(--accent);color:var(--on-accent);border-color:transparent;font-weight:600}\n.btn.danger{color:#B4533A;border-color:#B4533A}\n.btn:focus-visible,.row:focus-visible,.prow:focus-visible,.tab:focus-visible,.name-btn:focus-visible,.inp:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.inp{font:inherit;width:100%;min-width:0;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink)}\n.inp::placeholder{color:var(--muted);opacity:.8}\n.card[data-size=\"3x3\"] .inp{height:26px}\n.card[data-size=\"3x3\"] .btn{min-height:26px;padding:0 8px}\n.card[data-size=\"3x3\"] .btn.icon{width:26px}\n\n/* \u5217\u8868 */\n.hd{display:flex;align-items:center;justify-content:space-between;gap:8px;flex:none;min-width:0}\n.hd-t{min-width:0}\n.ttl{font-weight:700;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub-m{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.card[data-size=\"3x3\"] .sub-m{display:none}\n.card[data-size=\"6x3\"] .v-list{flex-direction:row;gap:12px}\n.card[data-size=\"6x3\"] .v-list .hd{flex-direction:column;align-items:stretch;justify-content:flex-start;width:96px;gap:10px}\n.rows{display:flex;flex-direction:column;gap:4px;flex:1;min-height:0;min-width:0;overflow:auto}\n.rows.flat{flex:none;overflow:visible}\n.rows.plans{align-content:start}\n.card[data-size=\"6x6\"] .rows.plans{display:grid;grid-template-columns:1fr 1fr;grid-auto-rows:min-content;gap:8px}\n.prow{flex:none;display:grid;grid-template-columns:auto minmax(0,1fr);grid-template-areas:\"nm nm\" \"am mt\" \"br br\";gap:2px 8px;align-items:baseline;width:100%;padding:7px 9px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper);color:var(--ink);font:inherit;text-align:left;cursor:pointer}\n.prow .nm{grid-area:nm;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.prow .am{grid-area:am;font-weight:800;font-size:15px;white-space:nowrap;font-variant-numeric:tabular-nums}\n.prow .mt{grid-area:mt;font-size:11px;color:var(--muted);text-align:right;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.prow .bar{grid-area:br;margin-top:4px}\n.card[data-size=\"3x3\"] .prow .mt,.card[data-size=\"3x3\"] .prow .bar,.card[data-size=\"6x3\"] .prow .bar{display:none}\n.empty{display:flex;flex-direction:column;gap:4px;align-items:flex-start;justify-content:center;padding:10px;border:1px dashed var(--line);border-radius:10px;color:var(--muted);font-size:12px}\n.empty-t{color:var(--ink);font-weight:600;font-size:13px}\n.empty.small{flex:none}\n.v-list>.empty{flex:1;min-height:0}\n\n/* \u8fdb\u5ea6\u6761 */\n.bar{display:flex;height:6px;border-radius:3px;background:var(--soft);overflow:hidden}\n.bar i{display:block;height:100%}\n.bar .a,.dot.a{background:var(--accent)}\n.bar .b,.dot.b{background:var(--accent-alt)}\n\n\n/* \u65b9\u6848\u8be6\u60c5 */\n.side{display:flex;flex-direction:column;gap:6px;min-width:0;flex:none}\n.card[data-size=\"3x3\"] .side{gap:4px}\n.main{display:flex;flex-direction:column;gap:6px;flex:1;min-height:0;min-width:0}\n.card[data-size=\"6x3\"] .v-plan{flex-direction:row;gap:10px}\n.card[data-size=\"6x3\"] .v-plan .side{width:150px}\n.top{display:flex;align-items:center;gap:4px;min-width:0}\n.name-btn{flex:1;min-width:0;display:flex;align-items:center;gap:4px;height:28px;padding:0 8px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--ink);font:inherit;font-weight:700;cursor:pointer;text-align:left}\n.name-btn:hover{background:var(--soft)}\n.name-t{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dots{color:var(--muted);flex:none}\n.card[data-size=\"3x3\"] .name-btn{height:26px;padding:0 4px}\n.add .tx{display:inline}\n.card[data-size=\"3x3\"] .add .tx,.card[data-size=\"3x6\"] .add .tx{display:none}\n.card[data-size=\"3x3\"] .add,.card[data-size=\"3x6\"] .add{width:28px;padding:0}\n\n.total{display:flex;flex-direction:column;gap:2px;min-width:0}\n.total .lb{font-size:11px;color:var(--muted)}\n.big{font-size:var(--big);font-weight:800;line-height:1.15;white-space:nowrap;font-variant-numeric:tabular-nums;color:var(--ink)}\n.big.m{font-size:calc(var(--big)*.82)}\n.big.s{font-size:calc(var(--big)*.68)}\n.big.xs{font-size:calc(var(--big)*.54)}\n.card[data-size=\"3x3\"] .total{flex-direction:row;align-items:baseline;justify-content:space-between;gap:8px}\n.card[data-size=\"3x3\"] .brk{display:none}\n.brk{display:flex;flex-direction:column;gap:5px;margin-top:4px}\n.lg{display:grid;grid-template-columns:8px auto minmax(0,1fr) auto;align-items:center;gap:6px;font-size:12px}\n.lg .dot{width:8px;height:8px;border-radius:2px}\n.lg .k{color:var(--muted);white-space:nowrap}\n.lg .v{text-align:right;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}\n.lg .h{display:none;color:var(--muted);font-size:11px;white-space:nowrap}\n.card[data-size=\"6x6\"] .lg .h{display:inline}\n.formula{display:none;font-size:11px;color:var(--muted)}\n.card[data-size=\"6x6\"] .formula{display:block}\n.card[data-size=\"6x3\"] .brk{margin-top:6px}\n\n/* \u9875\u7b7e\u4e0e\u660e\u7ec6\u884c */\n.tabs{display:flex;gap:4px;flex:none;align-items:stretch}\n.tab{flex:1;min-width:0;display:flex;flex-direction:column;align-items:flex-start;padding:3px 8px;border:1px solid var(--line);border-radius:8px;background:transparent;color:var(--ink);font:inherit;cursor:pointer;line-height:1.25}\n.tab small{font-size:10px;color:var(--muted);white-space:nowrap}\n.tab b{font-size:12px;white-space:nowrap;font-variant-numeric:tabular-nums}\n.tab[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);border-color:transparent}\n.tab[aria-pressed=\"true\"] small{color:var(--on-accent)}\n.row{flex:none;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:1px 8px;align-items:center;width:100%;min-height:38px;padding:5px 9px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit;text-align:left;cursor:pointer}\n.row .nm{font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.row .dt{grid-column:1;font-size:11px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.row .am{grid-column:2;grid-row:1/span 2;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}\n.row.one .am{grid-row:1}\n.scroll{flex:1;min-height:0;overflow:auto;display:flex;flex-direction:column;gap:10px}\n.sec{flex:none;display:flex;flex-direction:column;gap:4px}\n.sec-hd{display:flex;align-items:center;gap:8px;min-width:0}\n.sec-hd .t{font-weight:700;white-space:nowrap}\n.sec-hd .n{display:none;color:var(--muted);font-size:11px;white-space:nowrap}\n.card[data-size=\"6x6\"] .sec-hd .n{display:inline}\n.sec-hd .s{flex:1;min-width:0;text-align:right;font-weight:700;white-space:nowrap;font-variant-numeric:tabular-nums}\n\n/* \u8868\u5355 */\n.ftop{display:flex;align-items:baseline;justify-content:space-between;gap:8px;flex:none;min-width:0}\n.ftop-l{display:flex;align-items:center;gap:6px;min-width:0}\n.card[data-size=\"3x3\"] .ftop .sub-m{display:none}\n.form{display:flex;flex-direction:column;gap:6px;flex:1;min-height:0;min-width:0;overflow:auto}\n.card[data-size=\"3x3\"] .form{gap:4px}\n.fgrid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:6px}\n.card[data-size=\"3x3\"] .fgrid{gap:4px}\n.fld{display:flex;flex-direction:column;gap:2px;min-width:0}\n.fld.full{grid-column:1/-1}\n.fld .lb{font-size:11px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.sub{display:flex;justify-content:space-between;align-items:baseline;gap:8px;padding:4px 8px;border-radius:8px;background:var(--soft);font-size:12px;flex:none}\n.sub span{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.sub b{white-space:nowrap;font-variant-numeric:tabular-nums}\n.card[data-size=\"3x3\"] .sub.note{display:none}\n.err{font-size:11px;color:#B4533A;font-weight:600;flex:none}\n.err:empty{display:none}\n.acts{display:flex;flex-wrap:wrap;align-items:center;gap:6px;flex:none}\n.acts .btn{flex:1}\n.acts .ask{flex:1 1 100%;font-size:12px;color:#B4533A;font-weight:600}\n.card[data-size=\"3x3\"] .acts{gap:4px}\n.card[data-size=\"6x6\"] .form{max-width:360px}\n";
// ---- 纯函数：金额一律以「分」为单位累加，避免浮点误差 ----
function centsOf(x){var n=Number(x);if(!isFinite(n))return 0;return Math.round(n*100+1e-7);}
function workCents(it){return centsOf(Number(it.hours)*Number(it.rate));}
function costCents(it){return centsOf(it.amount);}
function sumBy(list,fn){var t=0;(list||[]).forEach(function(x){t+=fn(x);});return t;}
function planTotals(p){
  var labor=sumBy(p.items,workCents);
  var cost=sumBy(p.costs,costCents);
  var hours=sumBy(p.items,function(i){return Number(i.hours)||0;});
  return {labor:labor,cost:cost,total:labor+cost,hours:hours};
}
function yuan(c,trim){
  var neg=c<0;c=Math.abs(c);
  var whole=Math.floor(c/100),frac=c%100;
  var w=String(whole).replace(/\B(?=(\d{3})+(?!\d))/g,',');
  var s=(neg?'-':'')+'¥'+w;
  if(frac||!trim)s+='.'+(frac<10?'0':'')+frac;
  return s;
}
function numText(n){return String(Math.round(Number(n)*100)/100);}
function rateText(n){return yuan(centsOf(n),true);}
function sizeClass(s){var l=s.length;return l<=10?'':(l<=12?'m':(l<=14?'s':'xs'));}
function parseNum(v,max){
  var t=String(v==null?'':v).trim();
  if(t==='')return NaN;
  var n=Number(t);
  if(!isFinite(n)||n<0||n>max)return NaN;
  return n;
}
function normPlans(s){return Array.isArray(s&&s.plans)?s.plans:[];}


function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,percent,size}=ctx;
  const plans=normPlans(state);
  let view=ui.view||'list';
  const plan=plans.find(p=>p.id===ui.planId)||null;
  if(!plan&&view!=='list'&&view!=='new')view='list';
  const tabsMode=(size==='3x3'||size==='6x3');
  const tab=ui.tab==='cost'?'cost':'work';

  function btn(label,cls,onClick,attrs){
    return el('button',Object.assign({type:'button',class:'btn '+(cls||''),onclick:onClick},attrs||{}),label);
  }
  function go(patch){
    Object.assign(ui,{err:'',confirm:false,busy:false},patch);
    redraw();
  }
  function nextUi(patch){
    return Object.assign({view:'plan',planId:plan?plan.id:null,tab:tab,err:'',confirm:false,busy:false,draft:null,edit:null},patch);
  }
  function pct(v,t){return t>0?Math.max(0,Math.min(100,percent(v,t)))+'%':'0%';}
  function mapPlans(s,fn){
    return Object.assign({},s,{plans:normPlans(s).map(fn)});
  }

  // ---------- 方案列表 ----------
  function renderList(){
    const totals=plans.map(p=>planTotals(p).total);
    const max=Math.max.apply(null,[0].concat(totals));
    const hd=el('div',{class:'hd'},
      el('div',{class:'hd-t'},
        el('div',{class:'ttl'},'报价方案'),
        el('div',{class:'sub-m'},plans.length+' 个方案')),
      btn('+ 新建','pri',()=>go({view:'new',draft:{name:''},planId:null})));
    let body;
    if(!plans.length){
      body=el('div',{class:'empty'},
        el('div',{class:'empty-t'},'还没有报价方案'),
        el('div',{},'新建一个方案，再逐项填写工时与直接成本。'));
    }else{
      body=el('div',{class:'rows plans'},...plans.map((p,i)=>{
        const t=planTotals(p);
        const txt=yuan(t.total);
        const fill=el('i',{class:'a'});
        fill.style.width=pct(t.total,max);
        return el('button',{type:'button',class:'prow',title:p.name,
            onclick:()=>go({view:'plan',planId:p.id,tab:'work'})},
          el('span',{class:'nm'},p.name||'未命名方案'),
          el('span',{class:'am'},txt),
          el('span',{class:'mt'},'工时 '+(p.items||[]).length+' 项 · 成本 '+(p.costs||[]).length+' 项'),
          el('span',{class:'bar'},fill));
      }));
    }
    return [hd,body];
  }


  // ---------- 方案详情 ----------
  function openItem(kind,it){
    const d=it
      ?(kind==='work'?{name:it.name,hours:String(it.hours),rate:String(it.rate)}:{name:it.name,amount:String(it.amount)})
      :{name:'',hours:'',rate:'',amount:''};
    go({view:'item',tab:kind,edit:{kind:kind,id:it?it.id:null},draft:d});
  }
  function addBtn(kind){
    const label=kind==='work'?'添加工作项':'添加直接成本';
    return el('button',{type:'button',class:'btn pri add',title:label,'aria-label':label,onclick:()=>openItem(kind,null)},
      el('span',{class:'plus'},'+'),
      el('span',{class:'tx'},kind==='work'?' 工作项':' 成本'));
  }
  function itemRow(kind,it){
    const isW=kind==='work';
    const amt=yuan(isW?workCents(it):costCents(it));
    const kids=[
      el('span',{class:'nm'},it.name||'未命名'),
      el('span',{class:'am'},amt)];
    if(isW)kids.push(el('span',{class:'dt'},numText(it.hours)+' 小时 × '+rateText(it.rate)+'/时'));
    return el('button',{type:'button',class:'row'+(isW?'':' one'),title:it.name,onclick:()=>openItem(kind,it)},...kids);
  }
  function listNodes(kind){
    const arr=(kind==='work'?plan.items:plan.costs)||[];
    if(!arr.length){
      return [el('div',{class:'empty small'},kind==='work'
        ?'还没有工作项。填写预计小时和时薪后计入人工。'
        :'还没有直接成本。可添加材料、差旅等。')];
    }
    return arr.map(it=>itemRow(kind,it));
  }
  function tabBtn(kind,label,cents,cnt){
    return el('button',{type:'button',class:'tab','aria-pressed':String(tab===kind),
        onclick:()=>{ui.tab=kind;redraw();}},
      el('small',{},label+' · '+cnt),
      el('b',{},yuan(cents,true)));
  }
  function section(kind,t){
    const isW=kind==='work';
    const arr=(isW?plan.items:plan.costs)||[];
    return el('section',{class:'sec'},
      el('div',{class:'sec-hd'},
        el('span',{class:'t'},isW?'工时':'直接成本'),
        el('span',{class:'n'},arr.length+' 项'+(isW?' · '+numText(t.hours)+' 小时':'')),
        el('span',{class:'s'},yuan(isW?t.labor:t.cost)),
        addBtn(kind)),
      el('div',{class:'rows flat'},...listNodes(kind)));
  }

  function renderPlan(){
    const t=planTotals(plan);
    const tt=yuan(t.total);
    const top=el('div',{class:'top'},
      btn('‹','icon',()=>go({view:'list',planId:null}),{'aria-label':'返回方案列表',title:'返回方案列表'}),
      el('button',{type:'button',class:'name-btn',title:plan.name,'aria-label':'方案设置：'+plan.name,
          onclick:()=>go({view:'settings',draft:{name:plan.name||''}})},
        el('span',{class:'name-t'},plan.name||'未命名方案'),
        el('span',{class:'dots'},'⋯')));
    if(size==='3x3')top.appendChild(addBtn(tab));

    const fa=el('i',{class:'a'}),fb=el('i',{class:'b'});
    fa.style.width=pct(t.labor,t.total);
    fb.style.width=pct(t.cost,t.total);
    const brk=el('div',{class:'brk'},
      el('div',{class:'bar'},fa,fb),
      el('div',{class:'lg'},el('i',{class:'dot a'}),el('span',{class:'k'},'人工'),
        el('span',{class:'v'},yuan(t.labor)),el('span',{class:'h'},numText(t.hours)+' 小时')),
      el('div',{class:'lg'},el('i',{class:'dot b'}),el('span',{class:'k'},'直接成本'),
        el('span',{class:'v'},yuan(t.cost)),el('span',{class:'h'},(plan.costs||[]).length+' 项')),
      el('div',{class:'formula'},'总报价 = Σ(小时 × 时薪) + 直接成本'));
    const total=el('div',{class:'total'},
      el('div',{class:'lb'},'总报价'),
      el('div',{class:'big '+sizeClass(tt),title:tt},tt),
      brk);
    const side=el('div',{class:'side'},top,total);

    let main;
    if(tabsMode){
      const tr=[tabBtn('work','工时',t.labor,(plan.items||[]).length),
                tabBtn('cost','成本',t.cost,(plan.costs||[]).length)];
      if(size==='6x3')tr.push(addBtn(tab));
      main=el('div',{class:'main'},
        el('div',{class:'tabs'},...tr),
        el('div',{class:'rows'},...listNodes(tab)));
    }else{
      main=el('div',{class:'main'},
        el('div',{class:'scroll'},section('work',t),section('cost',t)));
    }
    return [side,main];
  }


  // ---------- 明细表单 ----------
  function makeField(d,key,label,opts,onChange,onEnter){
    const attrs={class:'inp',type:opts.number?'number':'text',value:d[key]==null?'':String(d[key]),
      placeholder:opts.ph||'','aria-label':label,
      oninput:()=>{d[key]=inp.value;onChange();},
      onkeydown:(e)=>{if(e.key==='Enter'){e.preventDefault();onEnter();}}};
    if(opts.number){attrs.inputmode='decimal';attrs.step='any';attrs.min='0';}
    else attrs.maxlength='40';
    const inp=el('input',attrs);
    return el('label',{class:'fld'+(opts.full?' full':'')},el('span',{class:'lb'},label),inp);
  }

  function renderItem(){
    const e=ui.edit||{kind:tab,id:null};
    const isW=e.kind==='work';
    const key=isW?'items':'costs';
    const existing=e.id?(plan[key]||[]).find(x=>x.id===e.id)||null:null;
    const d=ui.draft||(ui.draft={});
    const errEl=el('div',{class:'err',role:'alert'},ui.err?'! '+ui.err:'');
    const subVal=el('b',{},'');
    function showErr(m){ui.err=m;errEl.textContent=m?'! '+m:'';}
    function refresh(){calc();showErr('');}
    function calc(){
      let c=0;
      if(isW){
        const h=parseNum(d.hours,99999),r=parseNum(d.rate,999999);
        if(!isNaN(h)&&!isNaN(r))c=centsOf(h*r);
      }else{
        const a=parseNum(d.amount,99999999);
        if(!isNaN(a))c=centsOf(a);
      }
      subVal.textContent=yuan(c);
    }
    function save(){
      if(ui.busy)return;
      const name=String(d.name||'').trim();
      if(!name)return showErr('请填写名称');
      let rec;
      if(isW){
        const h=parseNum(d.hours,99999),r=parseNum(d.rate,999999);
        if(isNaN(h))return showErr('预计小时请填 0 到 99999 的数字');
        if(isNaN(r))return showErr('时薪请填 0 到 999999 的数字');
        rec={name:name,hours:h,rate:r};
      }else{
        const a=parseNum(d.amount,99999999);
        if(isNaN(a))return showErr('金额请填 0 到 99999999 的数字');
        rec={name:name,amount:a};
      }
