      if(ui.busy)return;
      const name=String(d.name||'').trim()||fb;
      ui.busy=true;
      const id=uid();
      commit(s=>Object.assign({},s,{plans:normPlans(s).concat([{id:id,name:name,items:[],costs:[]}])}),
