    }
    function rename(){
      if(ui.busy)return;
      const name=String(d.name||'').trim();
      if(!name)return showErr('请填写方案名称');
      ui.busy=true;
      const pid=plan.id;
      commit(s=>mapPlans(s,p=>p.id===pid?Object.assign({},p,{name:name}):p),
        nextUi({})).catch(()=>{ui.busy=false;showErr('保存失败，请重试');});
    }
    function duplicate(){
      if(ui.busy)return;
      ui.busy=true;
      const pid=plan.id,nid=uid();
      commit(s=>{
        const src=normPlans(s).find(p=>p.id===pid);
        if(!src)return s;
        const copy={id:nid,name:(src.name||'未命名方案')+' 副本',
          items:(src.items||[]).map(i=>Object.assign({},i,{id:uid()})),
          costs:(src.costs||[]).map(i=>Object.assign({},i,{id:uid()}))};
        return Object.assign({},s,{plans:normPlans(s).concat([copy])});
      },nextUi({planId:nid,tab:'work'})).catch(()=>{ui.busy=false;showErr('复制失败，请重试');});
    }
    function removePlan(){
      if(ui.busy)return;
      ui.busy=true;
      const pid=plan.id;
      commit(s=>Object.assign({},s,{plans:normPlans(s).filter(p=>p.id!==pid)}),
        nextUi({view:'list',planId:null})).catch(()=>{ui.busy=false;showErr('删除失败，请重试');});
    }
    const field=makeField(d,'name','方案名称',{ph:isNew?fb:'如：基础版',full:true},()=>showErr(''),isNew?create:rename);
    let acts;
    if(isNew){
      acts=[btn('取消','',()=>go({view:'list',draft:null})),btn('创建','pri',create)];
    }else if(ui.confirm){
      acts=[el('span',{class:'ask'},'删除整个方案及其全部明细？'),
        btn('确认删除','danger',removePlan),btn('保留','',()=>go({confirm:false}))];
    }else{
      acts=[btn('保存','pri',rename),btn('复制方案','',duplicate),btn('删除','danger',()=>go({confirm:true}))];
    }
    const kids=[el('div',{class:'fgrid'},field)];
    if(!isNew){
      const t=planTotals(plan);
      kids.push(el('div',{class:'sub note'},
        el('span',{},'工时 '+(plan.items||[]).length+' 项 · 成本 '+(plan.costs||[]).length+' 项'),
        el('b',{},yuan(t.total))));
    }
    kids.push(errEl,el('div',{class:'acts'},...acts));
    const back=isNew
      ?el('span',{class:'ttl'},'新建方案')
      :el('div',{class:'ftop-l'},
        btn('‹','icon',()=>go({view:'plan',draft:null}),{'aria-label':'返回方案',title:'返回方案'}),
        el('span',{class:'ttl'},'方案设置'));
    return [el('div',{class:'ftop'},back),el('div',{class:'form'},...kids)];
  }

  function render(){
    const shell=el('div',{class:'shell v-'+(view==='settings'||view==='new'||view==='item'?'form':view)});
    let nodes;
    if(view==='list')nodes=renderList();
    else if(view==='plan')nodes=renderPlan();
    else if(view==='item')nodes=renderItem();
    else nodes=renderPlanForm(view==='new');
    nodes.forEach(n=>shell.appendChild(n));
    root.appendChild(shell);
  }
  render();
}

